    const og = this.ctx.createGain(); og.gain.value = 0.12;
    o1.connect(f); o2.connect(f); f.connect(og); og.connect(bus);
    o1.start(t); o2.start(t); lfo.start(t);
    this.ambient = { o1, o2, lfo, bus, f };
  }

