    glass.position.z = .02; g.add(glass);
    // frames
    g.add(box(w + .16, .08, .08, frameMat, 0, h / 2 + .04, .05));
    g.add(box(w + .16, .08, .08, frameMat, 0, -h / 2 - .04, .05));
    g.add(box(.08, h + .16, .08, frameMat, -w / 2 - .04, 0, .05));
    g.add(box(.08, h + .16, .08, frameMat, w / 2 + .04, 0, .05));
    g.add(box(.05, h, .06, frameMat, 0, 0, .05));
    g.add(box(w, .05, .06, frameMat, 0, 0, .05));
    group.add(g);
    return g;
  }

