    this.enemyId = 0;
    this.lastDamage = 0;
    this.trigger = false;
    this.shellPump = 0;
    this.buildLevel();
  }

  buildLevel() {
    this.buildMap();
    this.buildAtmosphere();
    this.buildProps();
    this.buildPlayer();
    this.buildWeapon();
    this.setupSpawn();
    this.uiUpdate();
  }

