    const wax = new THREE.MeshStandardMaterial({ color: '#e8d3a9', roughness: .8, emissive: '#ffab55', emissiveIntensity: .18 });
    const hold = new THREE.MeshStandardMaterial({ color: '#7b6847', metalness: .6, roughness: .35 });
