function startGame() {
  if (state !== 'title') return;
  audio.init();
  audio.setAmbient('neighborhood');
  audio.ui();
  startingTime();
  ui.startScreen.classList.add('fade-out');
  setTimeout(() => ui.startScreen.classList.add('hidden'), 750);
  state = 'neighborhood';
  setHudMode('neighborhood');
  updateSouls(0);
