async (page) => {
  await page.setViewportSize({width:1280,height:800});
  await page.reload();
  await page.waitForTimeout(1000);
  await page.evaluate(() => window.__subdivision.startGame());
  await page.waitForTimeout(500);
  const out=[];
  out.push({lockedStart: await page.evaluate(()=>{const h=window.__subdivision.neighborhood.houses.find(h=>h.def.id==='hollow');return {locked:h.locked,state:window.__subdivision.state};})});
  for (const id of ['miller','vega','ashby','glass','hollow']) {
    if (id==='hollow') {
      out.push({beforeHollow: await page.evaluate(()=>({cleared:window.__subdivision.neighborhood.countCleared(), locked:window.__subdivision.neighborhood.houses.find(h=>h.def.id==='hollow').locked}))});
    }
    await page.evaluate(id => window.__subdivision.enterHouseById(id), id);
    await page.waitForTimeout(900);
    const info = await page.evaluate(() => { const l=window.__subdivision.level; return l?{state:l.state,waves:l.waves.length,w:l.waveIndex}:null; });
    let last=null;
    for (let w=0; w<12; w++) {
      const r=await page.evaluate(()=>{
        const l=window.__subdivision.level; if(!l) return {err:'no level'};
        if(l.state==='intro'){l.introTimer=0;l.update(.016);}
        if(l.state==='intermission'){l.waveDelay=0;l.update(.016);}
        if(l.state==='combat') for(const e of l.enemies) if(!e.dead) l.killEnemy(e);
        return {state:l.state,wave:l.waveIndex,exit:l.exitActive,living:l.enemies.filter(e=>!e.dead).length};
      });
      last=r; if(r.state==='cleared') break;
      await page.waitForTimeout(40);
    }
    const fin=await page.evaluate(()=>{const l=window.__subdivision.level;l.pos.copy(l.startPos);l.update(.016);return {near:l.exitNear,ok:l.requestExit()};});
    await page.waitForTimeout(1000);
    const after=await page.evaluate(()=>({state:window.__subdivision.state,cleared:window.__subdivision.neighborhood.countCleared(),victory:!document.getElementById('victoryScreen').classList.contains('hidden')}));
    out.push({id,info,last,fin,after});
    if (id==='hollow') {
      await page.screenshot({path:'screenshots/g-victory.jpg', type:'jpeg', quality:82, timeout:30000});
    }
  }
  return JSON.stringify(out);
}
EOF
